// Offline support. After one visit online, the app and all its features open without a
// connection. Files are served from this cache; nothing the user opens is ever stored here.
//
// VERSION and FILES are generated by tools/update-sw.py. A new VERSION installs alongside the
// old one and takes over only when the user chooses to reload, so work in progress is safe.

const CACHE_PREFIX = 'lk-pdf-studio-';
const VERSION = '39728b356772';
const FILES = [
    './',
    './css/app.css',
    './fonts/Lora-Variable.woff',
    './img/apple-touch-icon.png',
    './img/icon-192.png',
    './img/icon-512.png',
    './js/app.js',
    './js/pdf-utils.js',
    './js/preview-modal.js',
    './js/qpdf-engine.js',
    './js/samples.js',
    './js/ws-editor.js',
    './js/ws-organizer.js',
    './js/ws-security.js',
    './js/zip.js',
    './manifest.webmanifest',
    './vendor/fontkit.umd.min.js',
    './vendor/fonts/NotoSans-Regular.ttf',
    './vendor/jspdf.umd.min.js',
    './vendor/pdf-lib.min.js',
    './vendor/pdf.min.mjs',
    './vendor/pdf.worker.min.mjs',
    './vendor/qpdf.js',
    './vendor/qpdf.wasm'
];
const CACHE = CACHE_PREFIX + VERSION;

self.addEventListener('install', (event) => {
    event.waitUntil((async () => {
        const cache = await caches.open(CACHE);
        // Bypass the HTTP cache so a new version never mixes in stale files.
        await cache.addAll(FILES.map((url) => new Request(url, { cache: 'reload' })));
    })());
});

self.addEventListener('activate', (event) => {
    event.waitUntil((async () => {
        const keys = await caches.keys();
        await Promise.all(keys.filter((k) => k.startsWith(CACHE_PREFIX) && k !== CACHE).map((k) => caches.delete(k)));
        await self.clients.claim();
    })());
});

self.addEventListener('message', (event) => {
    if (event.data === 'skipWaiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
    const req = event.request;
    if (req.method !== 'GET') return;
    const url = new URL(req.url);
    if (url.origin !== self.location.origin) return; // e.g. the page-view counter
    const scope = new URL(self.registration.scope);
    if (!url.pathname.startsWith(scope.pathname)) return;

    event.respondWith((async () => {
        const cache = await caches.open(CACHE);
        if (req.mode === 'navigate') {
            const page = await cache.match('./');
            if (page) return page;
            return fetch(req);
        }
        const hit = await cache.match(req, { ignoreSearch: true });
        return hit || fetch(req);
    })());
});
